#!/usr/bin/env node
// Claude Code PostToolUse hook (Edit, Write, MultiEdit) — generated by KeelWright.
// Formats and lint-fixes the edited file with the project's own tools. Problems the fixer can't
// solve are shown to Claude (exit 2) so it fixes them in the same turn.
//
// The tools come from `onEdit` in .claude/hooks/config.json — a list of
//   { "files": "<regex on the path>", "run": ["<command>", "<arg>", "{file}"], "report": true, "label": "Ruff" }
// run in order; "report": true sends a non-zero exit to Claude. "cwd": a folder (relative to the
// project) to run in — a workspace — where a relative command is looked up first, then at the
// project root. Without a config file the hook uses Prettier and ESLint from node_modules. A
// command that isn't installed is skipped.

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { basename, join, relative, resolve } from 'node:path';

const DEFAULT = [
  { run: ['node_modules/.bin/prettier', '--write', '--ignore-unknown', '--log-level', 'warn', '{file}'] },
  { files: '\\.(?:[cm]?[jt]sx?|astro|vue|svelte)$', run: ['node_modules/.bin/eslint', '--fix', '--no-warn-ignored', '--max-warnings=0', '{file}'], report: true, label: 'ESLint' },
];

let input = null;
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  process.exit(0);
}
const filePath = input?.tool_input?.file_path;
if (!filePath) process.exit(0);
const root = process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd();
const file = resolve(root, filePath);
const rel = relative(root, file).split('\\').join('/');
if (!existsSync(file) || rel.startsWith('..') || /(^|\/)(node_modules|dist|build|target|\.venv|\.dart_tool|\.godot|\.git)\//.test(rel)) process.exit(0);

let steps = DEFAULT;
const configFile = join(root, '.claude/hooks/config.json');
if (existsSync(configFile)) {
  try {
    steps = JSON.parse(readFileSync(configFile, 'utf8')).onEdit ?? [];
  } catch (err) {
    process.stderr.write(`.claude/hooks/config.json is not valid JSON (${err.message}); fix it so files are formatted on edit.\n`);
    process.exit(2);
  }
}

for (const step of steps) {
  if (!Array.isArray(step.run) || !step.run.length) continue;
  if (step.files && !new RegExp(step.files).test(rel)) continue;
  const [cmd, ...args] = step.run.map((a) => a.replaceAll('{file}', file));
  const cwd = step.cwd ? resolve(root, step.cwd) : root;
  const local = cmd.includes('/') ? [resolve(cwd, cmd), resolve(root, cmd)].find((p) => existsSync(p)) : null;
  if (cmd.includes('/') && !local) continue; // tool not installed in the project
  const r = spawnSync(local ?? cmd, args, { cwd, encoding: 'utf8', timeout: 60_000 });
  if (r.error) continue; // command not found
  if (step.report && r.status !== 0) {
    const label = step.label ?? basename(cmd);
    process.stderr.write(`${label} found problems in ${rel} that need a manual fix:\n${(r.stdout || r.stderr).trim()}\n`);
    process.exit(2);
  }
}
process.exit(0);
